def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    key=[[3,6,1],[9,3,7],[6,5,5]]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==0:
          for dr in range(3):
            for dc in range(3):
              rr,cc=r+dr-1,c+dc-1
              if 0<=rr<h and 0<=cc<w and key[dr][dc]!=5: out[rr][cc]=key[dr][dc]
    return out
